-- Central Paroquial — Diretório Arquidiocesano: carga do Catálogo 2026 (GERADO, não edite à mão).
-- Gerado por scripts/importar-catalogo.mjs a partir de catalogo-01.07.26.pdf (seções 7.13, 7.14a e 7.15).
-- 293 registros: paroquia_territorial 284, paroquia_pessoal 2, paroquia_militar 1, curato 1, area_pastoral 1, santuario 4.
-- Santuários: 15 (11 também paróquia, 4 independentes).
-- Rode DEPOIS de supabase/diretorio.sql e supabase/diretorio_santuarios.sql. Pode rodar de novo: atualiza os dados
-- do catálogo e NUNCA mexe em status nem no vínculo com parishes (ativação é outro script).
-- Campos que não aparecem no catálogo ficam NULL.

on conflict (catalog_code) do update set name = excluded.name, display_name = excluded.display_name, type = excluded.type, episcopal_region = excluded.episcopal_region, episcopal_region_name = excluded.episcopal_region_name, forania = excluded.forania, municipality = excluded.municipality, neighborhood = excluded.neighborhood, address = excluded.address, postal_code = excluded.postal_code, phone = excluded.phone, email = excluded.email, pastor_role = excluded.pastor_role, pastor_name = excluded.pastor_name, founded_on = excluded.founded_on, source_year = excluded.source_year, is_sanctuary = excluded.is_sanctuary, sanctuary_code = excluded.sanctuary_code, sanctuary_name = excluded.sanctuary_name, sanctuary_kind = excluded.sanctuary_kind, rector_name = excluded.rector_name, sanctuary_since = excluded.sanctuary_since, source_section = excluded.source_section, updated_at = now();

-- Sem código de paróquia (casam pelo slug): militar, área pastoral, paróquias que só têm ficha de santuário e santuários
on conflict (slug) do update set name = excluded.name, display_name = excluded.display_name, type = excluded.type, episcopal_region = excluded.episcopal_region, episcopal_region_name = excluded.episcopal_region_name, forania = excluded.forania, municipality = excluded.municipality, neighborhood = excluded.neighborhood, address = excluded.address, postal_code = excluded.postal_code, phone = excluded.phone, email = excluded.email, pastor_role = excluded.pastor_role, pastor_name = excluded.pastor_name, founded_on = excluded.founded_on, source_year = excluded.source_year, is_sanctuary = excluded.is_sanctuary, sanctuary_code = excluded.sanctuary_code, sanctuary_name = excluded.sanctuary_name, sanctuary_kind = excluded.sanctuary_kind, rector_name = excluded.rector_name, sanctuary_since = excluded.sanctuary_since, source_section = excluded.source_section, updated_at = now();

-- Conferência
select type, is_sanctuary, count(*) from parish_directory group by type, is_sanctuary order by type, is_sanctuary;
